#!/usr/bin/env python3
# Створено штучним інтелектом (Claude, Anthropic) на замовлення lokinyauv-create. / Generated by AI (Claude).
"""Оновлювач Proton для Steam: сам качає нові версії і перемикає вибрані ігри.

Команди:
  protonupd.py run            — для таймера: застосувати відкладене + раз на 12 год перевірити нові версії
  protonupd.py check          — перевірити нові версії зараз (і поставити)
  protonupd.py status         — показати ігри, версії
  protonupd.py install SRC TAG — поставити конкретну версію
  protonupd.py set APPID SRC [TAG] — прив'язати гру до джерела (і версії)
"""
import hashlib, json, os, re, shutil, subprocess, sys, tarfile, tempfile, time, urllib.request
from pathlib import Path

STEAM = Path.home() / ".local/share/Steam"
COMPAT = STEAM / "compatibilitytools.d"
CFG_VDF = STEAM / "config/config.vdf"
CONF = Path.home() / ".config/proton-updater/config.json"

# Джерела: repo, шаблон назви файлу, як з тегу отримати внутрішню назву в Steam
SOURCES = {
    "ge": {
        "title": "GE-Proton",
        "repo": "GloriousEggroll/proton-ge-custom",
        "asset": r"^(GE-Proton[\d\-]+)-x86_64\.tar\.gz$",
        "name": lambda tag: f"{tag}-x86_64",
        "match": r"^GE-Proton\d+-\d+-x86_64$",
    },
    "rtsp": {
        "title": "Proton-GE RTSP (для відео у VRChat)",
        "repo": "SpookySkeletons/proton-ge-rtsp",
        "asset": r"^(proton-rtsp-[\w.\-]+)\.tar\.gz$",
        "name": lambda tag: tag,
        "match": r"^proton-rtsp-",
    },
}
DEFAULT = {"games": {"438100": {"name": "VRChat", "source": "ge", "pin": None}},
           "keep": 2, "last_check": 0, "pending": {}}


def load():
    try:
        c = json.loads(CONF.read_text())
    except Exception:
        c = {}
    for k, v in DEFAULT.items():
        c.setdefault(k, json.loads(json.dumps(v)))
    return c


def save(c):
    CONF.parent.mkdir(parents=True, exist_ok=True)
    CONF.write_text(json.dumps(c, ensure_ascii=False, indent=1))


def http_json(url):
    req = urllib.request.Request(url, headers={"User-Agent": "proton-updater"})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)


def releases(src, n=30):
    s = SOURCES[src]
    out = []
    for r in http_json(f"https://api.github.com/repos/{s['repo']}/releases?per_page={n}"):
        if r.get("prerelease") or r.get("draft"):
            continue
        for a in r["assets"]:
            m = re.match(s["asset"], a["name"])
            if m:
                sha = next((x["browser_download_url"] for x in r["assets"] if x["name"] == a["name"] + ".sha512sum"
                            or x["name"] == a["name"][:-7] + ".sha512sum"), None)
                out.append({"tag": r["tag_name"], "name": s["name"](m.group(1)), "url": a["browser_download_url"],
                            "sha": sha, "page": r["html_url"], "date": r["published_at"][:10], "size": a["size"]})
                break
    return out


def installed(src=None):
    res = []
    for d in sorted(COMPAT.glob("*")):
        for k, s in SOURCES.items():
            if (src in (None, k)) and re.match(s["match"], d.name):
                res.append((k, d.name))
    return res


def install(rel, log=print):
    dest = COMPAT / rel["name"]
    if dest.exists():
        return dest
    COMPAT.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(dir=COMPAT.parent) as tmp:
        tmp = Path(tmp)
        f = tmp / "a.tar.gz"
        log(f"Качаю {rel['name']} ({rel['size'] // 1048576} МБ)…")
        req = urllib.request.Request(rel["url"], headers={"User-Agent": "proton-updater"})
        h = hashlib.sha512()
        with urllib.request.urlopen(req, timeout=60) as r, open(f, "wb") as o:
            while chunk := r.read(1 << 20):
                o.write(chunk); h.update(chunk)
        if rel["sha"]:
            want = urllib.request.urlopen(urllib.request.Request(rel["sha"], headers={"User-Agent": "proton-updater"}),
                                          timeout=30).read().split()[0].decode()
            if want != h.hexdigest():
                raise RuntimeError("Контрольна сума не збігається — не ставлю.")
            log("Контрольна сума збігається.")
        else:
            log("Автор не дав контрольної суми — пропускаю перевірку.")
        ex = tmp / "x"; ex.mkdir()
        with tarfile.open(f) as t:
            t.extractall(ex, filter="data")
        top = [p for p in ex.iterdir() if p.is_dir()]
        if len(top) != 1:
            raise RuntimeError("Несподіваний вміст архіву.")
        shutil.move(str(top[0]), str(dest))
    log(f"Встановлено {rel['name']}.")
    return dest


# ---------- Steam config.vdf ----------
def steam_running():
    return subprocess.run(["pgrep", "-x", "steam"], capture_output=True).returncode == 0


def current_tool(appid):
    t = CFG_VDF.read_text(encoding="utf-8")
    i = t.find('"CompatToolMapping"')
    m = re.compile(r'"%s"\s*\{\s*"name"\s*"([^"]*)"' % appid).search(t, i) if i >= 0 else None
    return m.group(1) if m else None


def set_tool(appid, tool):
    if steam_running():
        raise RuntimeError("Steam запущений")
    t = CFG_VDF.read_text(encoding="utf-8")
    i = t.find('"CompatToolMapping"')
    if i < 0:
        raise RuntimeError("Немає CompatToolMapping у config.vdf")
    pat = re.compile(r'("%s"\s*\{\s*"name"\s*")[^"]*(")' % appid)
    m = pat.search(t, i)
    if m:
        t = t[:m.start()] + m.group(1) + tool + m.group(2) + t[m.end():]
    else:
        j = t.index("{", i) + 1
        blk = ('\n\t\t\t\t\t"%s"\n\t\t\t\t\t{\n\t\t\t\t\t\t"name"\t\t"%s"\n\t\t\t\t\t\t"config"\t\t""\n'
               '\t\t\t\t\t\t"priority"\t\t"250"\n\t\t\t\t\t}' % (appid, tool))
        t = t[:j] + blk + t[j:]
    shutil.copy2(CFG_VDF, str(CFG_VDF) + ".bak-protonupd")
    CFG_VDF.write_text(t, encoding="utf-8")


def steam_games():
    out = {}
    for f in (STEAM / "steamapps").glob("appmanifest_*.acf"):
        t = f.read_text(errors="ignore")
        n = re.search(r'"name"\s*"([^"]*)"', t)
        if n and not re.search(r"Proton|Steam Linux Runtime|SteamVR|Steamworks", n.group(1)):
            out[f.stem.split("_")[1]] = n.group(1)
    return dict(sorted(out.items(), key=lambda x: x[1].lower()))


# ---------- логіка ----------
def notify(msg):
    subprocess.run(["notify-send", "-a", "Оновлювач Proton", "-i", "system-software-update", "Proton", msg],
                   capture_output=True)


def wanted_for(src, game, rels):
    """Яку версію треба мати для гри: закріплена або найновіша."""
    if game.get("pin"):
        return next((r for r in rels if r["tag"] == game["pin"] or r["name"] == game["pin"]), None)
    return rels[0] if rels else None


def apply_pending(c, log=print):
    if not c["pending"]:
        return
    if steam_running():
        return
    for appid, tool in list(c["pending"].items()):
        if (COMPAT / tool).exists():
            set_tool(appid, tool)
            log(f"{c['games'].get(appid, {}).get('name', appid)} → {tool}")
            notify(f"{c['games'].get(appid, {}).get('name', appid)} тепер на {tool}")
        del c["pending"][appid]
    save(c)


def game_running():
    return subprocess.run(["pgrep", "-f", "reaper SteamLaunch"], capture_output=True).returncode == 0


def restart_steam(c, log=print):
    """Закрити Steam, застосувати відкладені перемикання, запустити Steam знову."""
    if game_running():
        raise RuntimeError("Зараз запущена гра — спершу вийди з неї.")
    if steam_running():
        log("Закриваю Steam…")
        subprocess.run(["steam", "-shutdown"], capture_output=True)
        for _ in range(90):
            if not steam_running():
                break
            time.sleep(1)
        else:
            raise RuntimeError("Steam не закрився за 90 с.")
        time.sleep(2)
    apply_pending(c, log)
    log("Запускаю Steam…")
    subprocess.Popen(["steam"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)


def check(c, log=print):
    cache = {}
    for appid, g in c["games"].items():
        src = g["source"]
        if src not in cache:
            cache[src] = releases(src)
        rel = wanted_for(src, g, cache[src])
        if not rel:
            continue
        install(rel, log)
        if current_tool(appid) != rel["name"]:
            c["pending"][appid] = rel["name"]
    c["last_check"] = time.time()
    save(c)
    cleanup(c, log)
    if c["pending"] and steam_running():
        notify("Нова версія Proton готова. Закрий Steam — і гра перемкнеться сама.")


def cleanup(c, log=print):
    used = {current_tool(a) for a in c["games"]} | set(c["pending"].values())
    for src in SOURCES:
        have = [n for s, n in installed(src)]
        have.sort(key=lambda n: [int(x) if x.isdigit() else 0 for x in re.split(r"\D+", n)], reverse=True)
        keep = set(have[:c["keep"]]) | used
        for n in have:
            if n not in keep:
                shutil.rmtree(COMPAT / n, ignore_errors=True)
                log(f"Прибрала стару версію {n}")


def run():
    c = load()
    apply_pending(c)
    if time.time() - c["last_check"] > 12 * 3600:
        try:
            check(c)
        except Exception as e:
            print("Не вдалося перевірити:", e, file=sys.stderr)
        apply_pending(c)


def main(a):
    cmd = a[0] if a else "status"
    c = load()
    if cmd == "run":
        run()
    elif cmd == "check":
        check(c); apply_pending(c)
    elif cmd == "restart":
        restart_steam(c)
    elif cmd == "status":
        for appid, g in c["games"].items():
            print(f"{g['name']} ({appid}): джерело {g['source']}, у Steam: {current_tool(appid)}, "
                  f"закріплено: {g.get('pin') or 'ні (остання)'}, відкладено: {c['pending'].get(appid, '-')}")
        print("Встановлено:", ", ".join(n for _, n in installed()))
    elif cmd == "install":
        rel = next(r for r in releases(a[1], 100) if r["tag"] == a[2] or r["name"] == a[2])
        install(rel)
    elif cmd == "set":
        appid, src = a[1], a[2]
        c["games"][appid] = {"name": steam_games().get(appid, appid), "source": src, "pin": a[3] if len(a) > 3 else None}
        save(c)
    else:
        print(__doc__)


if __name__ == "__main__":
    main(sys.argv[1:])
